command:
/**
 * Starship Shield Management
 * Adjust, recharge, or divert auxiliary energy to shields on the selected starship.
 */
const token = canvas.tokens.controlled[0];
const actor = token?.actor;

if (!actor || actor.type !== "darkspace.Ship") {
  ui.notifications.warn("Please select a Starship token first.");
} else {
  const hp = actor.system?.attributes?.hp?.value ?? 0;
  const maxHp = actor.system?.attributes?.hp?.max ?? 0;
  const ac = actor.system?.attributes?.ac?.value ?? 10;

  new Dialog({
    title: `Shield & Power Control: ${actor.name}`,
    content: `
      <form class="darkspace-dialog">
        <p><b>Ship:</b> ${actor.name} | <b>Hull:</b> ${hp}/${maxHp} HP | <b>AC:</b> ${ac}</p>
        <p>Choose tactical shield operation:</p>
      </form>
    `,
    buttons: {
      recharge: {
        icon: '<i class="fas fa-shield-alt"></i>',
        label: "Emergency Shield Boost (+1d6 HP)",
        callback: async () => {
          const r = await new Roll("1d6").evaluate();
          await r.render();
          const newHp = Math.min(maxHp, hp + r.total);
          await actor.update({ "system.attributes.hp.value": newHp });
          ChatMessage.create({
            speaker: ChatMessage.getSpeaker({ actor }),
            flavor: `<b>Shield Modulation</b> &mdash; Emergency Shield Boost`,
            content: `<p>Shield capacitors routed to defense grid! Restored <b>${r.total}</b> points. Current Hull: <b>${newHp}/${maxHp}</b>.</p>`
          });
        }
      },
      divert: {
        icon: '<i class="fas fa-bolt"></i>',
        label: "Overcharge Shields (+2 AC this round)",
        callback: async () => {
          ChatMessage.create({
            speaker: ChatMessage.getSpeaker({ actor }),
            flavor: `<b>Tactical Power Diversion</b>`,
            content: `<p>Auxiliary reactor energy channeled directly into deflection coils! <b>+2 AC</b> against incoming fire for 1 round.</p>`
          });
        }
      },
      overload: {
        icon: '<i class="fas fa-radiation"></i>',
        label: "Shield Collapse / Vent",
        callback: async () => {
          ChatMessage.create({
            speaker: ChatMessage.getSpeaker({ actor }),
            flavor: `<b>Shield Grid Collapse</b>`,
            content: `<p style="color: #F44336;"><b>WARNING:</b> Shield arrays overwhelmed! Energy vented into the void to prevent core feedback.</p>`
          });
        }
      }
    }
  }).render(true);
}
